-- Generated by Murakumo: load tpch_erp.customer (append), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/customer/ that were not loaded before.
create or replace temp table new_rows as
select cast(c_custkey as BIGINT) as c_custkey, cast(c_name as VARCHAR) as c_name, cast(c_address as VARCHAR) as c_address, cast(c_nationkey as INTEGER) as c_nationkey, cast(c_phone as VARCHAR) as c_phone, cast(c_acctbal as DECIMAL(15,2)) as c_acctbal, cast(c_mktsegment as VARCHAR) as c_mktsegment, cast(c_comment as VARCHAR) as c_comment, filename
from read_json('landing/tpch_erp/customer/customer_*.jsonl', format = 'newline_delimited', filename = true, columns = {'c_custkey': 'BIGINT', 'c_name': 'VARCHAR', 'c_address': 'VARCHAR', 'c_nationkey': 'INTEGER', 'c_phone': 'VARCHAR', 'c_acctbal': 'DECIMAL(15,2)', 'c_mktsegment': 'VARCHAR', 'c_comment': 'VARCHAR'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'customer');
-- Append: the new files' rows are added.
insert into raw_tpch_erp.customer (c_custkey, c_name, c_address, c_nationkey, c_phone, c_acctbal, c_mktsegment, c_comment, _ingested_at, _batch_id)
select c_custkey, c_name, c_address, c_nationkey, c_phone, c_acctbal, c_mktsegment, c_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'customer', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
